// Realistic synthetic ban list for generalization testing of src/engine.js (from review round 2; run by test/realistic.test.js).
// ~360 well-known real books, films, textbooks, study guides and manga, typed the way a school maintainer would over 20 years:
// inverted articles ("Giver, The"), typos in titles and authors, ~40% missing authors, "Et Al", "Last, First", initials,
// series / all-titles rows, volumes, grades, number titles, a few Arabic rows, Banned By codes (Ministry, UAS, RS, KES, HUBS,
// "KES / Ministry", "Minstry", "MOE", blanks), Type values and year ranges.
//
// No sample data: every row here is invented from public book / film titles. Rows are in the "Sheet1" tab, sorted by title
// the way the real list is, starting at sheet row 4. Row ids are mnemonic strings (toRow keeps them as row.testId).
//
// USE
//   const { rows, queries } = require('./fixtures/realistic-list.js');
//   const { toRow } = require('./helpers/sample.js');
//   const R = rows.map((r, i) => toRow(r, i)); const ix = E.buildIndex(R, { aliases: require('../aliases.json') });
//   per query: res = E.search(q.q, ix, { enter: !!q.enter })
//
// QUERY FIELDS (all optional except q)
//   main:    [ids] each must be in res.main (Match or Close)          -- "main-list recall"
//   any:     [ids] each must be in main, possible or isbnPrefix        -- "any-tier recall" (main ids count here too)
//   notMain: [ids] none may be in res.main                              -- false positives
//   ok:      [ids] extra rows allowed in main (legitimate matches the teacher does not need)
//            flood = main rows outside main ∪ any ∪ ok; 2 or more is a flood. A query with main: [] and exactly one extra main
//            row counts as a false positive on an unlisted title.
//   first:   id that must be res.main[0];  before: [[a, b]] a must come before b in main
//   firstPossible: id that must be res.possible[0];  possibleWithin: [[id, n]] id must be among the first n Possible hits
//   note / noteNot: [{ row, text }] that row's hit.notes must (not) contain text
//   hint:    hint code that must be present;  state: expected res.state
//   prd:     the PRD table row / section the expectation comes from
//   finding: the review-2 finding (GEN-n) the query reproduced on the engine as of 2cc76a5
//
// test/realistic.test.js checks recall, floods and false positives over every query, and scaleQueries on scaleRows() (~1,180
// rows); it lists the queries that stay as PRD-justified exceptions. Status is derived with CensorSheet.parseBannedBy, as the
// page does.
