// ---- optional: the list at ~1,200 rows ----
// scaleRows() adds the families a 20-year list accumulates (manga volumes, graded textbooks, yearly almanacs, numbered series)
// and returns every row re-sorted alphabetically with new sheet rows, as the real list is kept. The hand-written queries keep
// their main/any expectations at this size (their flood counts do not apply: the new rows are legitimate extra matches);
// scaleQueries hold the checks that only show at size.
function scaleRows() {
  const extra = [];
  const add = (id, title, author = '', bannedBy = 'KES', type = 'Book', year = '2015-2016') => extra.push({ id, tab: 'Sheet1', title, author, isbn: '', bannedBy, type, year, memo: '' });
  for (let v = 2; v <= 40; v++) add('NAR' + v, `Naruto Vol. ${v}`, v % 3 ? '' : 'Masashi Kishimoto', 'HUBS', 'Manga');
  for (let v = 1; v <= 12; v++) if (v !== 2) add('DN' + v, `Death Note Volume ${v}`, '', 'Ministry', 'Manga');
  for (let v = 1; v <= 60; v++) if (v !== 47) add('OP' + v, `One Piece Volume ${v}`, v % 4 ? '' : 'Eiichiro Oda', 'HUBS', 'Manga');
  for (let v = 1; v <= 30; v++) if (v !== 3) add('AOT' + v, `Attack on Titan vol ${v}`, '', 'Ministry', 'Manga');
  for (const g of ['K', 1, 2, 3, 6, 7, 8]) add('SF' + g, `Science Fusion Grade ${g}`, 'Houghton Mifflin Harcourt', 'UAS', 'Textbook');
  for (const g of ['K', 1, 3, 4, 5, 6]) add('WON' + g, `Wonders Reading/Writing Workshop Grade ${g}`, 'McGraw Hill', 'UAS', 'Textbook');
  for (const g of ['K', 1, 2, 3, 4, 5]) for (let m = 1; m <= 10; m++) if (!(g === 'K' && m === 4)) add(`IR${g}M${m}`, `Into Reading Grade ${g} Module ${m}`, 'HMH', 'UAS', 'Textbook');
  for (let y = 2005; y <= 2024; y++) if (y !== 2015) add('GWR' + y, `Guinness World Records ${y}`, '', 'HUBS', 'Reference');
  for (let y = 2010; y <= 2024; y++) if (y !== 2018) add('NGK' + y, `National Geographic Kids Almanac ${y}`, '', 'KES', 'Reference');
  for (let v = 1; v <= 18; v++) if (v !== 3) add('WK' + v, `Diary of a Wimpy Kid #${v}`, v % 2 ? 'Jeff Kinney' : '', 'HUBS', 'Book');
  for (let v = 2; v <= 36; v++) add('MTH' + v, `Magic Tree House #${v}`, '', 'RS', 'Book');
  for (let v = 1; v <= 62; v++) add('GB' + v, `Goosebumps #${v}`, v % 5 ? '' : 'R.L. Stine', 'KES', 'Book');
  for (let v = 2; v <= 13; v++) add('SOU' + v, `Series of Unfortunate Events, A - Book ${v}`, 'Lemony Snicket', 'RS', 'Book');
  for (let v = 1; v <= 30; v++) add('BSC' + v, `Baby-Sitters Club #${v}`, 'Ann M. Martin', 'UAS', 'Book');
  for (let v = 1; v <= 25; v++) if (v !== 5) add('WOF' + v, `Wings of Fire Book ${v}`, v % 2 ? '' : 'Tui T. Sutherland', 'HUBS', 'Book');
  for (let s = 1; s <= 10; s++) add('FR' + s, `Friends Season ${s}`, '', 'Ministry', 'DVD');
  for (let s = 1; s <= 30; s++) if (s !== 5) add('SIM' + s, `Simpsons, The - Season ${s}`, '', 'KES', 'DVD');
  for (let s = 1; s <= 6; s++) if (s !== 2) add('GLEE' + s, `Glee Season ${s}`, '', 'Ministry', 'DVD');
  for (let v = 1; v <= 20; v++) if (v !== 3) add('FG' + v, `Family Guy Volume ${v}`, '', 'Ministry', 'DVD');
  add('SHRK3', 'Shrek the Third', '', 'RS', 'DVD'); add('SHRK4', 'Shrek Forever After', '', 'RS', 'DVD');
  for (let v = 1; v <= 100; v++) add('ND' + v, `Nancy Drew #${v}`, v % 4 ? '' : 'Carolyn Keene', 'RS', 'Book', '2004-2005');
  for (let v = 1; v <= 100; v++) add('HB' + v, `Hardy Boys #${v}`, '', 'RS', 'Book', '2004-2005');
  for (let v = 1; v <= 100; v++) add('BOX' + v, `Boxcar Children #${v}`, v % 3 ? '' : 'Gertrude Chandler Warner', 'KES', 'Book');
  for (let v = 1; v <= 12; v++) add('CU' + v, `Captain Underpants #${v}`, 'Dav Pilkey', 'UAS', 'Book');
  for (let v = 1; v <= 11; v++) add('DM' + v, `Dog Man #${v}`, '', 'UAS', 'Graphic Novel');
  return rows.concat(extra).sort((a, b) => a.title.localeCompare(b.title, 'en', { numeric: true, sensitivity: 'base' }))
    .map((r, i) => Object.assign({}, r, { row: 4 + i }));
}
